def build():
    ids = [q[0] for q in Q]
    assert len(ids) == len(set(ids)), "duplicate IDs"
    for q in Q:
        assert q[4] in DIMENSIONS, q
        assert q[5] in LEVELS, q
    return {
        "version": 1,
        "about": "Traveller question bank for country pages. Templates use {country}. Scores are kept per country.",
        "levels": LEVELS,
        "dimensions": DIMENSIONS,
        "questions": [dict(id=a, category=b, template=c, audience=d, dimension=e, level=f) for a, b, c, d, e, f in Q],
    }

if __name__ == "__main__":
    out = os.path.join(os.path.dirname(__file__), "question_bank.json")
